        "overview" => "Killers of the Flower Moon is a 2023 American epic crime drama film directed by Martin Scorsese, who co-wrote the screenplay with Eric Roth, based on the 2017 nonfiction book. It stars Leonardo DiCaprio, Robert De Niro, Lily Gladstone, and Jesse Plemons. Set in 1920s Oklahoma, it focuses on a series of murders of Osage members and relations in the Osage Nation after oil was discovered on tribal land. The tribal members had retained mineral rights on their reservation, but a corrupt local political boss sought to steal the wealth. It is the sixth feature film collaboration between Scorsese and DiCaprio, the tenth between Scorsese and De Niro, and the eleventh and final between Scorsese and composer Robbie Robertson, who died two months before the film's release and to whom the film is dedicated.",
