        "overview" => "The Theory of Everything is a 2014 biographical drama film produced by Working Title Films and directed by James Marsh. Set at the University of Cambridge, it details three decades of the life of the theoretical physicist Stephen Hawking. It was adapted by Anthony McCarten from the 2007 memoir Travelling to Infinity: My Life with Stephen by Jane Hawking, which deals with her relationship with her ex-husband Stephen Hawking, his diagnosis of motor neurone disease – also known as amyotrophic lateral sclerosis (ALS) – and his success in the field of physics. The film stars Eddie Redmayne and Felicity Jones, with Charlie Cox, Emily Watson, Simon McBurney, Christian McKay, Harry Lloyd, and David Thewlis featured in supporting roles. The film had its world premiere at the 2014 Toronto International Film Festival on 7 September 2014. It had its UK premiere on 1 January 2015.",
