        "trailer"  => "",
        "overview" => "Amores perros is a 2000 Mexican psychological drama film produced and directed by Alejandro González Iñárritu and written by Guillermo Arriaga, based on a story by both. Amores perros is the first installment in González Iñárritu's \"Trilogy of Death\", succeeded by 21 Grams and Babel. It makes use of the multi-narrative hyperlink cinema style and features an ensemble cast of Emilio Echevarría, Gael García Bernal, Goya Toledo, Álvaro Guerrero, Vanessa Bauche, Jorge Salinas, Adriana Barraza, and Humberto Busto. The film is constructed as a triptych: it contains three distinct stories connected by a car crash in Mexico City. The stories centre on: a teenager in the slums who gets involved in dogfighting; a model who seriously injures her leg; and a mysterious hitman. The stories are linked in various ways, including the presence of dogs in each of them.",
        "source"   => "https://en.wikipedia.org/wiki/Amores_perros",
    ),

