        "overview" => "Y tu mamá también is a 2001 Mexican coming-of-age erotic comedy-drama road film directed by Alfonso Cuarón, who co-wrote the screenplay with his brother Carlos Cuarón. The film follows two teenage boys who embark on a road trip with a woman in her late twenties and stars Diego Luna, Gael García Bernal, and Maribel Verdú, with narration by Daniel Giménez Cacho. Set in 1999, it unfolds against the backdrop of Mexico's political and economic realities at the close of seven uninterrupted decades of Institutional Revolutionary Party (PRI) presidencies and the rise of the opposition led by Vicente Fox.",
