        "overview" => "Crouching Tiger, Hidden Dragon is a 2000 wuxia film directed by Ang Lee and written for the screen by Wang Hui-ling, James Schamus, and Tsai Kuo-jung. It is based on the Chinese novel of the same name, serialized between 1941 and 1942 by Wang Dulu, the fourth part of his Crane-Iron Series. It stars Chow Yun-fat, Michelle Yeoh, Zhang Ziyi, Chang Chen and Cheng Pei-pei in the leading roles. Set in 18th-century Imperial China, the plot follows two master warriors, Li Mu Bai (Chow) and Yu Shu Lien (Yeoh), who are faced with their greatest challenge when the treasured Green Destiny sword is stolen by the mysterious thief Jen Yu (Zhang).",
