        "overview" => "Kung Fu Hustle is a 2004 martial arts action comedy film directed, produced and co-written by Stephen Chow, who also stars in the leading role, alongside Huang Shengyi, Yuen Wah, Yuen Qiu, Danny Chan Kwok-kwan and Leung Siu-lung in prominent roles. The story revolves around a murderous neighbourhood gang, a poor village with unlikely heroes and an aspiring gangster's fierce journey to find his true self. The martial arts choreography is supervised by Yuen Woo-ping. Film scholar Christina Klein describes Kung Fu Hustle as a transnational Chinese-language film whose mode of production is closely connected to its visual and narrative style.",
