        "overview" => "Ip Man is a 2008 Hong Kong biographical martial arts film based on the life of Ip Man, a grandmaster of the martial art Wing Chun and teacher of martial artist legend Bruce Lee. The film focuses on events in Ip's life that supposedly took place in the city of Foshan during the Sino-Japanese War. The film was directed by Wilson Yip, and stars Donnie Yen as the main character, with martial arts choreography by Sammo Hung. The film co-stars Simon Yam, Lynn Hung, Lam Ka-tung, Xing Yu, Hiroyuki Ikeuchi, and Tenma Shibuya. The film was a co-production between China and Hong Kong, and was the last film to be distributed by Mandarin Films.",
