        "trailer"  => "",
        "overview" => "Hera Pheri is a 2000 Indian Hindi-language comedy drama film directed by Priyadarshan and originally written by Siddique-Lal and adapted screenplay by Neeraj Vora, starring Akshay Kumar, Suniel Shetty, Paresh Rawal, Tabu, Om Puri, Asrani, and Gulshan Grover. The film is a remake of 1989 Malayalam film Ramji Rao Speaking which itself was inspired by the 1971 American TV film See The Man Run. It is the first instalment of the Hera Pheri franchise. The plot revolves around two tenants, Raju and Shyam, and their landlord, Baburao Ganpatrao Apte, who are in desperate need of money. They chance upon a ransom call through a cross-connection and hatch a plan to claim the ransom for themselves.",
