        "overview" => "Dil Chahta Hai is a 2001 Indian Hindi-language coming of age comedy drama film written and directed by Farhan Akhtar in his directorial debut, and produced by Ritesh Sidhwani under the newly formed Excel Entertainment banner. The film stars Aamir Khan, Saif Ali Khan, and Akshaye Khanna as three inseparable college friends navigating adulthood, relationships, and diverging life paths. It also features Preity Zinta, Sonali Kulkarni, and Dimple Kapadia in pivotal supporting roles. Set in contemporary urban India, the film explores themes of friendship, love, and self-discovery among upper-class youth.",
