        "overview" => "Bhool Bhulaiyaa (transl. Labyrinth) is a 2007 Indian Hindi-language psychological horror comedy film directed by Priyadarshan from a screenplay by Neeraj Vora and produced by T Series. It is a remake of the 1993 Malayalam-language film Manichitrathazhu written by Madhu Muttam and directed by Fazil, which is based on a 19th-century tragedy that happened at Madhu's Alummoottil tharavad in Muttom in central Travancore. The film stars Akshay Kumar, Vidya Balan, Shiney Ahuja, and Ameesha Patel, alongside Paresh Rawal, Rajpal Yadav, Manoj Joshi, Asrani, and Vikram Gokhale. The film score and soundtrack were composed by Ranjit Barot and Pritam respectively, with lyrics written by Sameer and Sayeed Quadri.",
