        "overview" => "Chak De! India is a 2007 Indian sports drama film directed by Shimit Amin, written by Jaideep Sahni and produced by Aditya Chopra under the banner of Yash Raj Films. The film stars Shah Rukh Khan as Kabir Khan, the former captain of the India men's national field hockey team. After a disastrous loss to Pakistan, Khan is ostracised from the sport owing to religious prejudice. 7 years later in an attempt to redeem himself, he becomes the coach of the India women's national field hockey team, with the goal of turning its 16 contentious players into an award-winning team.",
