        "overview" => "Taare Zameen Par, also known as Like Stars on Earth in English, is a 2007 Indian Hindi-language psychological drama film produced and directed by Aamir Khan. It stars Khan, with Darsheel Safary, Tanay Chheda, Vipin Sharma and Tisca Chopra. It explores the life and imagination of Ishaan (Safary), an artistically gifted 8-year-old boy whose poor academic performance leads his parents to send him to a boarding school, where a new art teacher Nikumbh suspects that he is dyslexic and helps him to overcome his reading disorder. The film focuses on raising awareness about dyslexia in children.",
