        "trailer"  => "",
        "overview" => "Brahmāstra: Part One – Shiva is a 2022 Indian Hindi-language fantasy action adventure film written and directed by Ayan Mukerji. The film is the first installment of a planned trilogy, which is itself planned to be part of a cinematic universe titled Āstraverse, and stars an ensemble cast including Amitabh Bachchan, Ranbir Kapoor, Alia Bhatt, Mouni Roy and Nagarjuna with Shah Rukh Khan in a special appearance. This is the first film of real-life couple Ranbir Kapoor and Alia Bhatt together. Drawing inspiration from tales in Hindu mythology, the story follows Shiva, an orphaned musician with pyrokinetic powers who discovers that he is an astra, a weapon of enormous energy. He attempts to prevent the strongest of the astras, the Brahmāstra, from falling into the hands of dark forces that share a history with him.",
