        "trailer"  => "",
        "overview" => "Baahubali: The Beginning is a 2015 Indian epic action film co-written and directed by S. S. Rajamouli, and produced by Shobu Yarlagadda and Prasad Devineni under Arka Media Works. Produced in the Telugu film industry, the film was shot in both Telugu and Tamil languages. It features Prabhas in a dual role alongside Rana Daggubati, Anushka, Tamannaah Bhatia, Ramya Krishnan, Sathyaraj, and Nassar. The first of a duology of films, it follows Sivudu, an adventurous young man who helps his love Avantika rescue Devasena, the princess of Kunthala who is now a prisoner under the tyrannical rule of king Bhallaladeva. The film is the first part of the duology. The story concludes in Baahubali 2: The Conclusion (2017).",
