        "overview" => "Premam (transl. Love) is a 2015 Indian Malayalam-language coming-of-age romantic comedy-drama film written, directed and edited by Alphonse Puthren. It was produced by Anwar Rasheed and stars Nivin Pauly and Sai Pallavi. It also features an ensemble supporting cast including Madonna Sebastian, Anupama Parameswaran, Shabareesh Varma, Krishna Sankar, Siju Wilson, Ananth Nag, Vinay Forrt, Soubin Shahir, Sharafudheen and others. The plot follows George (Nivin)’s romantic journey with his friends from their teens to adulthood. While George's first love turns out to be a disappointment, Malar (Pallavi), a college lecturer, rekindles his love interest. His romantic journey takes him through several stages, helping him find his purpose.",
