    "baahubali-2-the-conclusion" => array(
        "type"     => "movie",
        "format"   => "movie",
        "title"    => "Baahubali 2: The Conclusion",
        "year"     => 2017,
        "industry" => "south-indian",
        "studio"   => "Arka Media Works",
        "language" => "Telugu",
        "original" => "",
        "genres"   => array("fantasy", "action", "adventure"),
        "director" => "S. S. Rajamouli",
        "cast"     => array("Prabhas", "Rana Daggubati", "Anushka Shetty", "Sathyaraj"),
