        "banner"   => "",
        "trailer"  => "",
        "overview" => "Baahubali 2: The Conclusion is a 2017 Indian Telugu-language epic action drama film directed by S. S. Rajamouli, who co-wrote the script with V. Vijayendra Prasad. It was produced by Shobu Yarlagadda and Prasad Devineni under the banner Arka Media Works. The cast includes Prabhas in a dual and titular role, alongside Rana Daggubati, Anushka Shetty, Tamannaah Bhatia, Ramya Krishna, Sathyaraj, Nassar and Subbaraju. It is the sequel to Baahubali: The Beginning, as well as the final installment in the Baahubali film duology. The film is set in fictional medieval India and centers on the rivalry between siblings Amarendra Baahubali and Bhallaladeva. Bhallaladeva conspires against Amarendra, leading to his death at the hands of Kattappa. Years later, Amarendra's son seeks to avenge his father's demise. The film was primarily shot in Telugu, with a limited number of close-up scenes also filmed in Tamil for select actors.",
        "source"   => "https://en.wikipedia.org/wiki/Baahubali_2%3A_The_Conclusion",
    ),

