        "overview" => "KGF: Chapter 1 is a 2018 Indian Kannada-language period action film written and directed by Prashanth Neel, and produced by Vijay Kiragandur under the banner of Hombale Films. It is the first installment in the KGF series, followed by KGF: Chapter 2. The film stars Yash, Srinidhi Shetty, Vasishta N. Simha, Ramachandra Raju, Archana Jois, Anant Nag, Achyuth Kumar, Malavika Avinash, T. S. Nagabharana and B. Suresha. Filmed on a budget of ₹80 crore, it was the most expensive Kannada film at the time of its release. In the film, Rocky, a high-ranking mercenary, working for a prominent gold mafia in Bombay, seeks power and wealth in order to fulfill his mother's promise. Due to his high fame, the leaders of the gold mafia where he works hire him to assassinate Garuda, the son of the founder of Kolar Gold Fields.",
